<script>
document.addEventListener('DOMContentLoaded', function() {
  const keywords = [
    '[Graves] Style V13',
    '[XenGenTr] Style V13',
    'XenGenTr\\XGTStyleV13',
    'XGTStyleV13',
    'xgt_style_v13'
  ];

  document.querySelectorAll('.dataList-cell').forEach(cell => {
    const text = cell.textContent;
    if (keywords.some(keyword => text.includes(keyword))) {
      const row = cell.closest('.dataList-rowGroup, .dataList-row');
      if (row) {
        row.style.display = 'none';
      }
    }
  });
});
</script>

