<script>
  document.addEventListener('DOMContentLoaded', function() {
    var dataListCells = document.querySelectorAll('.dataList-cell');
    if (dataListCells.length > 0) {
      dataListCells.forEach(function(dataListCell) {
        if (dataListCell.textContent.includes('[Graves] Style V13') || dataListCell.textContent.includes('[XenGenTr] Style V13') || dataListCell.textContent.includes('XGTStyleV13')) {
          var dataListRowGroup = dataListCell.closest('.dataList-rowGroup');
          dataListRowGroup.style.display = 'none';
        }
      });
    } else {
      console.log('');
    }
  });
</script>
